package com.example.redpacket;
import android.app.*;import android.os.*;import android.content.*;import android.provider.Settings;import android.view.*;import android.widget.*;
public class MainActivity extends Activity {
 public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(32,48,32,24);TextView title=new TextView(this);title.setText("微信红包助手 · vivo 优化版");title.setTextSize(23);l.addView(title);TextView note=new TextView(this);note.setText("适配目标：微信 8.0.79（需真机验证）\n安全锁屏无法绕过；息屏不保证自动领取。\n请在 vivo 设置中允许自启动及后台运行。");note.setTextSize(15);l.addView(note);Switch sw=new Switch(this);sw.setText("启用自动识别红包");sw.setChecked(getSharedPreferences("MainActivity",0).getBoolean("enabled",false));sw.setOnCheckedChangeListener((v,c)->getSharedPreferences("MainActivity",0).edit().putBoolean("enabled",c).apply());l.addView(sw);TextView delay=new TextView(this);delay.setText("点击延迟（毫秒）");l.addView(delay);SeekBar seek=new SeekBar(this);seek.setMax(1800);seek.setProgress(getSharedPreferences("MainActivity",0).getInt("delay",300));seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int p,boolean u){delay.setText("点击延迟："+p+" 毫秒");if(u)getSharedPreferences("MainActivity",0).edit().putInt("delay",p).apply();}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});l.addView(seek);add(l,"开启无障碍服务",Settings.ACTION_ACCESSIBILITY_SETTINGS);add(l,"开启通知使用权",Settings.ACTION_NOTIFICATION_LISTENER_SETTINGS);add(l,"电池优化设置",Settings.ACTION_IGNORE_BATTERY_OPTIMIZATION_SETTINGS);setContentView(l);}
 void add(LinearLayout l,String text,String action){Button b=new Button(this);b.setText(text);b.setOnClickListener(v->{try{startActivity(new Intent(action));}catch(Exception e){Toast.makeText(this,"请在系统设置中手动开启",Toast.LENGTH_LONG).show();}});l.addView(b);}
}